use crate::aap::caps::state_read;

struct Node;

/// Keys tried in order in the 'subscriptions' store. The store has no list
/// operation, so the node can only ask for keys it already knows.
const KEYS: &[&str] = &["urls", "subscriptions", "feeds"];

/// Parse a JSON array of strings, such as `["https://a", "https://b"]`.
/// Returns `None` if the text is not a well-formed array of strings.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let chars: Vec<char> = s.trim().chars().collect();
    let mut i = 0usize;
    let n = chars.len();

    fn skip_ws(chars: &[char], i: &mut usize) {
        while *i < chars.len() && chars[*i].is_whitespace() {
            *i += 1;
        }
    }

    if n == 0 || chars[0] != '[' {
        return None;
    }
    i += 1;
    let mut out = Vec::new();
    skip_ws(&chars, &mut i);
    if i < n && chars[i] == ']' {
        i += 1;
        skip_ws(&chars, &mut i);
        return if i == n { Some(out) } else { None };
    }
    loop {
        skip_ws(&chars, &mut i);
        if i >= n || chars[i] != '"' {
            return None;
        }
        i += 1;
        let mut cur = String::new();
        loop {
            if i >= n {
                return None;
            }
            let c = chars[i];
            i += 1;
            match c {
                '"' => break,
                '\\' => {
                    if i >= n {
                        return None;
                    }
                    let e = chars[i];
                    i += 1;
                    match e {
                        '"' => cur.push('"'),
                        '\\' => cur.push('\\'),
                        '/' => cur.push('/'),
                        'b' => cur.push('\u{8}'),
                        'f' => cur.push('\u{c}'),
                        'n' => cur.push('\n'),
                        'r' => cur.push('\r'),
                        't' => cur.push('\t'),
                        'u' => {
                            if i + 4 > n {
                                return None;
                            }
                            let hex: String = chars[i..i + 4].iter().collect();
                            i += 4;
                            let code = u32::from_str_radix(&hex, 16).ok()?;
                            cur.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                        _ => return None,
                    }
                }
                _ => cur.push(c),
            }
        }
        out.push(cur);
        skip_ws(&chars, &mut i);
        if i >= n {
            return None;
        }
        match chars[i] {
            ',' => {
                i += 1;
            }
            ']' => {
                i += 1;
                skip_ws(&chars, &mut i);
                return if i == n { Some(out) } else { None };
            }
            _ => return None,
        }
    }
}

/// Parse a stored subscription value. It may be a JSON array of strings, or
/// plain text with one URL per line or comma-separated. Lines starting with
/// '#' are comments.
fn parse_urls(raw: &str) -> Vec<String> {
    let candidates: Vec<String> = match parse_json_string_array(raw) {
        Some(v) => v,
        None => raw
            .lines()
            .map(|l| l.trim())
            .filter(|l| !l.is_empty() && !l.starts_with('#'))
            .flat_map(|l| l.split(',').map(|p| p.trim().to_string()))
            .collect(),
    };

    let mut out: Vec<String> = Vec::new();
    for c in candidates {
        let u = c.trim();
        if u.is_empty() || u.chars().any(|ch| ch.is_whitespace() || ch.is_control()) {
            continue;
        }
        if !out.iter().any(|e| e == u) {
            out.push(u.to_string());
        }
    }
    out
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                let urls = parse_urls(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        // The contract requires `urls` to be present. With no subscriptions in
        // the store, there is nothing honest to return. The node traps here
        // rather than inventing feeds.
        panic!("LoadSubscriptions: no subscriptions found in the 'subscriptions' store");
    }
}

export!(Node);
